\caption{\method{}: Recursive Skill-Augmented RL}
\label{alg:skillrl}
\begin{algorithmic}[1]
    \REQUIRE Base model $\pi_{\text{base}}$, teacher $\mathcal{M}_T$, environment $\mathcal{E}$
    \ENSURE Trained policy $\pi_{\theta^*}$, evolved skill library $\skillbank{}^*$

    \STATE \textcolor{blue}{$\triangleright$ Experience-based Skill Distillation}
    \STATE $\mathcal{T}^+, \mathcal{T}^- \leftarrow \text{Rollout}(\pi_{\text{base}}, \mathcal{E})$
    \FORALL{$\tau^+ \in \mathcal{T}^+$}
        \STATE $s^+ \leftarrow \mathcal{M}_T(\tau^+)$
    \ENDFOR
    \FORALL{$\tau^- \in \mathcal{T}^-$}
        \STATE $s^- \leftarrow \mathcal{M}_T(\tau^-)$
    \ENDFOR

    \STATE \textcolor{blue}{$\triangleright$ Hierarchical Skill Library Construction}
    \STATE $\mathcal{S}_g \leftarrow$ general skills from distilled experiences
    \FORALL{task type $k$}
        \STATE $\mathcal{S}_k \leftarrow$ task-specific skills for category $k$
    \ENDFOR
    \STATE $\skillbank{} \leftarrow \mathcal{S}_g \cup \bigcup_k \mathcal{S}_k$

    \STATE \textcolor{blue}{$\triangleright$ Recursive Skill Evolution via RL}
    \STATE \textcolor{gray}{\textit{// Cold-start initialization}}
    \STATE $\mathcal{D}_{\text{SFT}} \leftarrow \mathcal{M}_T(\mathcal{E}, \skillbank{})$
    \STATE $\theta \leftarrow \text{SFT}(\pi_{\text{base}}, \mathcal{D}_{\text{SFT}})$; \quad $\pi_{\text{ref}} \leftarrow \pi_\theta$
    \STATE \textcolor{gray}{\textit{// RL with recursive evolution}}
    \FOR{epoch $= 1$ to $N$}
        \FORALL{task $d$}
            \STATE $\mathcal{S}_{\text{ret}} \leftarrow \text{Retrieve}(d, \skillbank{})$
            \STATE Sample $\{\tau^{(i)}\}_{i=1}^G \sim \pi_\theta(\cdot | d, \mathcal{S}_g, \mathcal{S}_{\text{ret}})$
            \STATE Compute $\{R_i\}_{i=1}^G$ and update $\theta$ via GRPO
        \ENDFOR
        \IF{validation epoch}
            \STATE $\mathcal{T}_{\text{val}}^- \leftarrow$ failed validation trajectories
            \STATE $\mathcal{S}_{\text{new}} \leftarrow \mathcal{M}_T(\mathcal{T}_{\text{val}}^-, \skillbank{})$
            \STATE $\skillbank{} \leftarrow \skillbank{} \cup \mathcal{S}_{\text{new}}$
        \ENDIF
    \ENDFOR
    \STATE \textbf{return} $\pi_\theta$, $\skillbank{}$
\end{algorithmic}

\caption{\sysname{} Evolution Loop}
\label{alg:loop}
\begin{algorithmic}[1]
\REQUIRE Task description $T$, workspace $W$, initial skill $S_0$
\ENSURE Evolved skill $S^*$
\STATE $\mathcal{I} \leftarrow \textsc{TaskInterpreter}(T)$ \hfill\COMMENT{explicit constraints from the task}
\STATE $V \leftarrow \textsc{CompileTaskVerifier}(\mathcal{I}, W)$ \hfill\COMMENT{$W$ grounds task-referenced data}
\STATE $(\tau_w, \tau_{wo}) \leftarrow \textsc{PairedExecution}(T, W, S_0)$
\STATE $D_0 \leftarrow \textsc{PACE}(\tau_w, \tau_{wo}, S_0)$ \hfill\COMMENT{first paired diagnosis}
\STATE $\textit{mode} \leftarrow \textsc{SelectMode}(\textsc{EffectivenessDelta}(D_0), \textsc{DiagnosisScope}(D_0))$ \hfill\COMMENT{lock Refine or Repair}
\STATE $S \leftarrow S_0$;\; $S_{\mathrm{acc}} \leftarrow S_0$;\; $H \leftarrow \varnothing$
\FOR{$t = 1, \ldots, 5$}
    \IF{$t > 1$}
        \STATE $\tau_w, \tau_{wo} \leftarrow \textsc{PairedExecution}(T, W, S)$
        \STATE $D_t \leftarrow \textsc{PACE}(\tau_w, \tau_{wo}, S)$
    \ELSE
        \STATE $D_t \leftarrow D_0$
    \ENDIF
    \STATE $\textit{verdict} \leftarrow \textsc{Aggregate}(D_t)$ \hfill\COMMENT{hurt has veto; mode unchanged}
    \STATE $H \leftarrow H \,\|\, [\textit{verdict}]$ \hfill\COMMENT{append to verdict history}
    \IF{$S \neq S_{\mathrm{acc}}$ \AND (\textit{verdict} = \textit{hurt} \OR $V(\tau_w)$ fails)}
        \STATE $S \leftarrow S_{\mathrm{acc}}$ \hfill\COMMENT{reject the edited candidate}
    \ELSE
        \IF{$V(\tau_w)$ passes}
            \STATE $S_{\mathrm{acc}} \leftarrow S$
        \ENDIF
        \IF{$t<5$ \AND \textsc{HasActionablePassages}$(D_t, \textit{mode})$}
            \STATE $S \leftarrow \textsc{SkillIterator}(S, \tau_w, \tau_{wo}, \textit{mode})$
        \ENDIF
    \ENDIF
    \IF{$S = S_{\mathrm{acc}}$ \AND \textsc{Converged}$(D_t, V(\tau_w), H)$} \STATE \textbf{break} \ENDIF
\ENDFOR
\RETURN $S_{\mathrm{acc}}$
\end{algorithmic}

