\caption{\textbf{Self-Evolutionary Framework \texttt{\ours}}}
\label{alg:ours_concise}
\begin{algorithmic}[1]
\REQUIRE Base LLM $\pi_{\text{base}}$; Iterations $T$; Samples $k$.
\STATE Initialize $\small \pi_{\theta}^{(0)} \leftarrow \pi_{\text{base}}$ and $\small \pi_{\phi}^{(0)} \leftarrow \pi_{\text{base}}$.
\FOR{each iteration $t = 1, \dots, T$}
    \STATE $\triangleright$ \textit{\textcolor{blue}{Curriculum Evolution (Train $\pi_{\theta}$)}}
    \STATE Initialize $\small \pi_{\theta} \leftarrow \pi_{\theta}^{(t-1)}$
    \STATE Generate a batch of tasks $X = \{x_i\} \sim \pi_{\theta}$
    \FOR{task $x_i \in X$}
        \STATE Sample $k$ responses $\{y_j\}_{j=1}^k \sim \pi_{\phi}^{(t-1)}(x_i)$
        \STATE Compute $R_{C}(x_i)$ using Eq.~\ref{eq:curr}
    \ENDFOR
    \STATE Update $\pi_\theta$ using $\mathcal{L}_{\text{GRPO}}$ with $(X, R_C)$ $\to$ $\pi_{\theta}^{(t)}$

    \STATE $\triangleright$ \textit{\textcolor{blue}{Executor Evolution (Train $\pi_{\phi}$) }}
    \STATE Generate $X_{\text{pool}} \sim \pi_{\theta}^{(t)}$ and filter to $\mathcal{D}^{(t)} = \{(x, \hat{p}, \tilde{y})\}$ where $|\hat{p}(x) - 0.5| \le \delta$

    \STATE Initialize $\pi_{\phi} \leftarrow \pi_{\phi}^{(t-1)}$
    \FOR{batch $B_\mathcal{D} = \{(x, \hat{p}(x), \tilde{y})\} \sim \mathcal{D}^{(t)}$}
        \STATE Initialize $\mathcal{T}_{\text{batch}}, \tilde{\mathcal{A}}_{\text{batch}}, \mathcal{P}_{\text{batch}}$
        \FOR{$(x, \hat{p}(x), \tilde{y}) \in B_\mathcal{D}$}
            \STATE Sample $k$ trajectories $\{\tau_i\}_{i=1}^k \sim \pi_{\phi}(x)$
            \STATE Compute rewards $R_i = \mathbb{I}(o_i = \tilde{y})$
            \STATE Compute scaled advantages $\tilde{A}_i \leftarrow A_i \cdot f(\hat{p}(x))$
            \STATE Add $\{\tau_i\}$ to $\mathcal{T}_{\text{batch}}$, $\{\tilde{A}_i\}$ to $\tilde{\mathcal{A}}_{\text{batch}}$, $\hat{p}(x)$ to $\mathcal{P}_{\text{batch}}$
        \ENDFOR
        \STATE Update $\pi_\phi$ using $\mathcal{L}_{\text{ADPO}}$ (Eq.~\ref{eq:adpo}) on collected batch
    \ENDFOR
    \STATE $\pi_{\phi}^{(t)} \leftarrow \pi_{\phi}$
\ENDFOR
\end{algorithmic}

\caption{Self-Play Training of Absolute Zero Reasoner (AZR)}
\label{alg:azr-training}
\begin{algorithmic}[1]
\Require Pretrained base LLM $\pi_\theta$; batch size $B$; \#references $K$; iterations $T$
\State $\mathcal D_{\text{ded}},\mathcal D_{\text{abd}},\mathcal D_{\text{ind}} \gets \textsc{InitSeeding}(\pi_\theta)$ \Comment{see §\ref{sec:seed}}

\For{$t \gets 1$ to $T$}

  \For{$b \gets 1$ to $B$}  \Comment{\textbf{PROPOSE PHASE}}
    \State $p \sim \mathcal D_{\text{abd}} \cup \mathcal D_{\text{ded}}$ \Comment{sample a program for induction task proposal}
    \State $\bigl\{i^n_\pi\bigr\}_{n=1}^{N},\;m_\pi \gets \pi_\theta^{\text{propose}}(\text{ind},p)$ \Comment{generate $N$ inputs and a description}
    \If{$\bigl\{(i^n_\pi,o^n_\pi)\bigr\}_{n=1}^{N} \gets \textsc{ValidateByExecuting}\bigl(p,\{i^n_\pi\},\textsc{syntax}\bigr)$} \Comment{validate I/Os, see §\ref{sec:filter}}
        \State $\mathcal D_{\text{ind}} \gets \mathcal D_{\text{ind}} \cup \bigl\{(p,\{(i^n_\pi,o^n_\pi)\},m_\pi)\bigr\}$ \Comment{update induction buffer}
    \EndIf

    \For{$\alpha \in \{\text{ded},\text{abd}\}$}
      \State $\bigl(p_k,i_k,o_k\bigr)_{k=1}^{K} \sim \mathcal D_{\alpha}$ \Comment{sample $K$ reference examples}
      \State $(p_\pi,i_\pi) \gets \pi_\theta^{\text{propose}}\!\bigl(\alpha,\{(p_k,i_k,o_k)\}\bigr)$
      \Comment{propose new task}
      \If{$o_\pi \gets \textsc{ValidateByExecuting}\bigl(p_\pi,i_\pi,\textsc{syntax,safety,determinism}\bigr)$} \Comment{see §\ref{sec:filter}}
        \State $\mathcal D_{\alpha} \gets \mathcal D_{\alpha} \cup \bigl\{(p_\pi,i_\pi,o_\pi)\bigr\}$ \Comment{if valid, update deduction or abduction buffers}
      \EndIf
    \EndFor
  \EndFor


  \ForAll{$\alpha \in \{\text{ded},\text{abd},\text{ind}\}$} \Comment{\textbf{SOLVE PHASE}}
    \State $(x,y^\star) \gets \textsc{SamplePrepareTasks}\bigl(\mathcal D_{\alpha},B,t\bigr)$
      \Comment{$x, y^\star$ prepared based on $\alpha$, see §\ref{sec:filter}\&\ref{sec:answer_verification}}
    \State $y_\pi \sim \pi_\theta^{\text{solve}}(x)$
  \EndFor


  \State \textbf{Reward:} Use proposed task triplets and solved answers to get $r_{propose}$ \& $r_{solve}$ \Comment{see §\ref{sec:roles}}
  \State \textbf{RL update:} use Task Relative REINFORCE++ to update $\pi_\theta$ \Comment{see §\ref{sec:trr}}
\EndFor
\end{algorithmic}

